<script setup>
import { onMounted, reactive, ref } from 'vue'; import { ElButton,ElDialog,ElInput,ElMessage,ElOption,ElPagination,ElSelect,ElTable,ElTableColumn,ElTag } from 'element-plus'; import * as api from '../api/adminHistory.js'; import AdminMediaAssetManager from '../components/AdminMediaAssetManager.vue'
const filters=reactive({page:1,pageSize:10,keyword:'',reviewStatus:'',status:'',featured:''});const rows=ref([]),total=ref(0),formVisible=ref(false),mediaVisible=ref(false),target=ref(null),editing=ref(false)
const blank=()=>({id:null,title:'',timeText:'',timePrecision:'year',year:null,month:null,day:null,summary:'',content:'',sourceName:'',sourceUrl:'',evidence:'',reviewStatus:'pending',status:0,isFeatured:0,sortOrder:0});const form=reactive(blank())
async function load(){try{const r=await api.getList(filters);rows.value=r.list;total.value=r.total}catch{ElMessage.error('历史列表暂时无法加载。')}}function reset(){Object.assign(filters,{page:1,pageSize:10,keyword:'',reviewStatus:'',status:'',featured:''});load()}function newEvent(){Object.assign(form,blank());editing.value=false;formVisible.value=true}async function edit(row){Object.assign(form,await api.getById(row.id));editing.value=true;formVisible.value=true}async function save(){try{if(editing.value)await api.update(form.id,form);else await api.create(form);formVisible.value=false;load();ElMessage.success('历史资料已保存。')}catch(e){ElMessage.error(e.message||'保存失败。')}}async function hide(row){try{await api.remove(row.id);load()}catch{ElMessage.error('隐藏失败。')}}function manage(row){target.value=row;mediaVisible.value=true}onMounted(load)
</script>
<template><section class="admin-history"><div class="admin-page-heading"><div><p class="eyebrow">HISTORY MANAGEMENT</p><h1>历史管理</h1></div><p>时间保持来源原始精度；只有“已核验 + 展示中”的资料可对游客公开。</p></div><div class="admin-filters"><ElInput v-model="filters.keyword" placeholder="搜索时间、标题或简介"/><ElSelect v-model="filters.reviewStatus" clearable placeholder="审核状态"><ElOption label="待核验" value="pending"/><ElOption label="已核验" value="verified"/><ElOption label="有冲突" value="conflict"/><ElOption label="已拒绝" value="rejected"/></ElSelect><ElSelect v-model="filters.status" clearable placeholder="展示状态"><ElOption label="展示" value="1"/><ElOption label="隐藏" value="0"/></ElSelect><ElSelect v-model="filters.featured" clearable placeholder="首页展示"><ElOption label="首页展示" value="1"/><ElOption label="非首页展示" value="0"/></ElSelect><ElButton type="primary" @click="filters.page=1;load()">查询</ElButton><ElButton @click="reset">重置</ElButton><ElButton type="primary" plain @click="newEvent">新增事件</ElButton></div><ElTable :data="rows" stripe><ElTableColumn prop="timeText" label="时间" width="120"/><ElTableColumn prop="title" label="事件标题" min-width="190"/><ElTableColumn label="审核" width="105"><template #default="{row}"><ElTag>{{ row.reviewStatus }}</ElTag></template></ElTableColumn><ElTableColumn label="展示" width="80"><template #default="{row}">{{row.status?'展示':'隐藏'}}</template></ElTableColumn><ElTableColumn label="首页" width="80"><template #default="{row}">{{row.isFeatured?'是':'否'}}</template></ElTableColumn><ElTableColumn prop="sourceName" label="来源" min-width="130"/><ElTableColumn label="操作" fixed="right" width="210"><template #default="{row}"><ElButton link @click="edit(row)">编辑</ElButton><ElButton link @click="manage(row)">图片</ElButton><ElButton link type="danger" @click="hide(row)">隐藏</ElButton></template></ElTableColumn></ElTable><ElPagination v-model:current-page="filters.page" :page-size="filters.pageSize" layout="total,prev,pager,next" :total="total" @current-change="load"/>
<ElDialog v-model="formVisible" :title="editing?'编辑历史事件':'新增历史事件'" width="min(95vw,780px)"><div class="history-form"><label>事件标题*<ElInput v-model="form.title"/></label><label>时间原文*<ElInput v-model="form.timeText" placeholder="如：1937年8月"/></label><label>时间精度*<ElSelect v-model="form.timePrecision"><ElOption label="年" value="year"/><ElOption label="月" value="month"/><ElOption label="日" value="day"/><ElOption label="季节" value="season"/><ElOption label="范围" value="range"/><ElOption label="未知" value="unknown"/></ElSelect></label><label>年份<ElInput v-model.number="form.year" type="number"/></label><label v-if="['month','day'].includes(form.timePrecision)">月份<ElInput v-model.number="form.month" type="number"/></label><label v-if="form.timePrecision==='day'">日期<ElInput v-model.number="form.day" type="number"/></label><label class="wide">简要介绍*<ElInput v-model="form.summary" type="textarea"/></label><label class="wide">详细内容<ElInput v-model="form.content" type="textarea"/></label><label>来源机构*<ElInput v-model="form.sourceName"/></label><label>来源页面 URL<ElInput v-model="form.sourceUrl"/></label><label class="wide">证据摘要*<ElInput v-model="form.evidence" type="textarea"/></label><label>审核状态<ElSelect v-model="form.reviewStatus"><ElOption label="待核验" value="pending"/><ElOption label="已核验" value="verified"/><ElOption label="有冲突" value="conflict"/><ElOption label="已拒绝" value="rejected"/></ElSelect></label><label>展示状态<ElSelect v-model="form.status"><ElOption label="展示" :value="1"/><ElOption label="隐藏" :value="0"/></ElSelect></label><label>首页峥嵘岁月展示<ElSelect v-model="form.isFeatured"><ElOption label="否" :value="0"/><ElOption label="是" :value="1"/></ElSelect></label><label>排序<ElInput v-model.number="form.sortOrder" type="number" min="0"/></label></div><template #footer><ElButton @click="formVisible=false">取消</ElButton><ElButton type="primary" @click="save">保存</ElButton></template></ElDialog><ElDialog v-model="mediaVisible" width="min(96vw,980px)" :title="`${target?.title||''} · 图片管理`"><AdminMediaAssetManager v-if="target" entity-type="history_event" :entity-id="target.id" :api="api"/></ElDialog></section></template>
<style scoped>.admin-page-heading{display:flex;justify-content:space-between;gap:24px;margin-bottom:24px}.admin-page-heading h1{margin:0}.admin-page-heading p{color:var(--muted);max-width:440px}.admin-filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.admin-filters :deep(.el-input),.admin-filters :deep(.el-select){width:220px}.history-form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.history-form label{display:grid;gap:6px}.wide{grid-column:span 2}@media(max-width:640px){.admin-page-heading,.history-form{display:block}.history-form label{margin-bottom:12px}.wide{grid-column:auto}}</style>
